"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["80443"],{40085(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca_requerida.recorte_de_competencia_duplicado","status":422,"titulo":"Duas bancas do mesmo tipo na mesma fase declaram o mesmo recorte de compet\xeancia"},"descricao":{"codigo":"uniplus.selecao.banca_requerida.recorte_de_competencia_duplicado","requisitos":[],"oQueAconteceu":["Duas bancas do mesmo tipo na mesma fase declaram exatamente as mesmas categorias de\\ndocumento.","Declarar o recorte serve para distinguir bancas que o tipo sozinho n\xe3o distingue.\\nDuas bancas de an\xe1lise documental com o mesmo recorte continuam indistingu\xedveis: o\\nparecer que o candidato recebe n\xe3o diz qual delas o julgou, e o recurso n\xe3o sabe\\ncontra quem se dirige. Preencher as duas com o mesmo conte\xfado cumpre a letra da\\nexig\xeancia sem cumprir o efeito, e por isso \xe9 recusado junto com a omiss\xe3o.","A compara\xe7\xe3o \xe9 feita como **conjunto**: a ordem em que as categorias s\xe3o declaradas\\nn\xe3o importa, e duas bancas que citam as mesmas categorias em ordens diferentes\\ndeclaram o mesmo recorte.","A recusa nomeia o c\xf3digo da banca e lista as categorias do recorte repetido."],"comoResolver":["Dois caminhos, conforme o desenho da fase:","- **As duas bancas julgam coisas diferentes.** Reparta as categorias entre elas,\\n  conforme o que cada uma de fato analisa. Cada categoria continua podendo aparecer\\n  [uma \xfanica vez](/erros/uniplus.selecao.banca_requerida.categoria_duplicada_no_recorte)\\n  dentro de um mesmo recorte.\\n- **As duas julgam o mesmo conjunto.** Ent\xe3o n\xe3o s\xe3o duas bancas \u2014 remova a\\n  repetida. Com uma banca do tipo na fase, o recorte deixa de ser exigido.","N\xe3o h\xe1 um terceiro caminho: esvaziar o recorte de uma das duas para desfazer a\\nigualdade devolve a\\n[recusa por recorte ausente](/erros/uniplus.selecao.banca_requerida.recorte_de_competencia_obrigatorio),\\nporque a fase continua com duas bancas do mesmo tipo.","O preflight de conformidade mostra esta pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_recorte_de_competencia_das_bancas`."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca requerida"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);